func (_q *LessonQuery) loadAttempts(ctx context.Context, query *LessonAttemptQuery, nodes []*Lesson, init func(*Lesson), assign func(*Lesson, *LessonAttempt)) error {
	fks := make([]driver.Value, 0, len(nodes))
	nodeids := make(map[uuid.UUID]*Lesson)
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	query.withFKs = true
	if len(query.ctx.Fields) > 0 {
		query.ctx.AppendFieldOnce(lessonattempt.FieldLessonID)
	}
	query.Where(predicate.LessonAttempt(func(s *sql.Selector) {
		s.Where(sql.InValues(s.C(lesson.AttemptsColumn), fks...))
	}))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.LessonID
		if fk == nil {
			return fmt.Errorf(`foreign-key "lesson_id" is nil for node %v`, n.ID)
		}
		node, ok := nodeids[*fk]
		if !ok {
			return fmt.Errorf(`unexpected referenced foreign-key "lesson_id" returned %v for node %v`, *fk, n.ID)
		}
		assign(node, n)
	}
	return nil
}

